routes.counterexample:
class Res
  destructor
    Console.WriteLine("closed");
  end destructor;
  public method Flush()
    Console.WriteLine("flush");
  end Flush;
end Res;
class Base
  protected owned _r: Res := new Res();
  destructor
    _r.Flush();                // runs after Derived's destructor (§28.4)
  end destructor;
end Base;
class Derived: Base
  destructor
    using var r := move _r;    // K9.3: bare take of a non-nullable field of this object
  end destructor;              // r disposed here: "closed"
end Derived;
class Demo
  public static method Main()
    using var d := new Derived();
  end Main;                    // Base's destructor reads `_r`: null typed non-null,
end Demo;                      //   no flag (K4.1) and no recorded clause (K4.3)

class Res
  public readonly property N: int;
  public constructor(n: int)  N := n;  end constructor;
  destructor
    Console.WriteLine($"closed {N}");
    if N = 1 then throw new InvalidOperationException("boom"); end;
  end destructor;
end Res;
class Holder
  private owned _r: Res := new Res(1);
  private _slots: [2 owned]Res := [new Res(1), new Res(4)];
  public method Swap() => _r := new Res(2);    // Res(1) throws: store abandoned, Res(2) unwound
  public method Reset() => _slots := [new Res(5), new Res(6)];  // §28.7: slots "left empty"
  public method Peek(): int => _r.N + _slots[1].N;
end Holder;
class Demo
  public static method Main()
    using var h := new Holder();
    try h.Swap(); catch InvalidOperationException => Console.WriteLine("caught 1") end;
    try h.Reset(); catch InvalidOperationException => Console.WriteLine("caught 2") end;
    Console.WriteLine(h.Peek());   // _r: Res(1)'s reclaimed block, or a hole? _slots: "empty"
  end Main;                        // h's cascade: frees Res(1)'s block again (reading 1)?
end Demo;
